// Never trust a webhook body blindly (same rule as contracts.ts's validatePublishResponse,
// applied here to what's coming IN instead of what's going out). A malformed or truncated
// request must not reach the Google Calendar node.
const body = $input.first().json.body || {};
const scheduleVersion = body.scheduleVersion;
const events = body.events;
const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri'];
const inDay = (v) => typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= 24 * 60;

if (typeof scheduleVersion !== 'string' || !scheduleVersion || !Array.isArray(events)) {
  throw new Error('Malformed publish request: scheduleVersion and events are required.');
}

// TODO once Workflow B is standing up: compare `scheduleVersion` against the last version this
// workflow actually approved (persisted by that step) and reject a stale/changed schedule here.
// Today the frontend's own approval dialog is the only gate, so this step only checks shape.

const clean = [];
for (const e of events) {
  const ok =
    e && typeof e.studentId === 'string' && typeof e.studentName === 'string' && DAYS.includes(e.day) &&
    inDay(e.start) && inDay(e.end) && e.end > e.start && typeof e.shiftId === 'string' && e.shiftId;
  if (ok) clean.push({ studentId: e.studentId, studentName: e.studentName, day: e.day, start: e.start, end: e.end, shiftId: e.shiftId });
}
if (!clean.length) throw new Error('No valid events in the publish request.');

// One item per event from here on, each carrying the schedule version so later nodes
// (and the final response) don't need to look it up again.
return clean.map((e) => ({ json: { ...e, scheduleVersion } }));

// Look up this shift in the persisted shiftId -> googleEventId map so the next node can
// create a NEW event or update the SAME event instead of always creating — that's what makes
// retries and re-publishes idempotent (see docs/N8N_ARCHITECTURE.md, "Idempotency strategy").
//
// This uses n8n's own workflow static data as the store, so no external database is required
// to get real idempotency for a pilot. If ShiftFit later gets a real backend (see ROADMAP.md
// v3), swap this lookup for a query against that instead — the shape (shiftId -> googleEventId)
// stays the same either way.
const store = $getWorkflowStaticData('global');
if (!store.shiftfitSyncMap) store.shiftfitSyncMap = {};
const existingEventId = store.shiftfitSyncMap[$json.shiftId] || null;
return { json: { ...$json, existingEventId } };

// Write shiftId -> googleEventId into the same static-data map 'Diff vs. previously synced
// events' read from, so the NEXT publish (or a retry of this one) recognizes these events
// as already-synced instead of creating duplicates. Then build the response contracts.ts
// expects (see PublishResponse / PublishEventResult in src/services/automation/contracts.ts).
const store = $getWorkflowStaticData('global');
if (!store.shiftfitSyncMap) store.shiftfitSyncMap = {};

const results = [];
let scheduleVersion = null;
for (const item of $input.all()) {
  // The Google Calendar node's own output usually replaces $json with the calendar event it
  // returned, so the original shiftId/scheduleVersion are read back from the node BEFORE it
  // (n8n keeps this linkage via paired items). Adjust the referenced node name here if you
  // rename 'Diff vs. previously synced events'.
  const original = $('Diff vs. previously synced events').itemMatching(item.pairedItem?.item ?? 0)?.json ?? {};
  const shiftId = original.shiftId;
  scheduleVersion = scheduleVersion || original.scheduleVersion;
  const googleEventId = item.json.id || item.json.googleEventId;
  if (shiftId && googleEventId) {
    store.shiftfitSyncMap[shiftId] = googleEventId;
    results.push({ shiftId, status: original.existingEventId ? 'updated' : 'created', googleEventId });
  } else if (shiftId) {
    // The calendar node didn't return an id — treat as failed rather than silently dropping it.
    results.push({ shiftId, status: 'failed', error: 'Google Calendar did not return an event id.' });
  }
}
return [{ json: { scheduleVersion, results } }];
